'use client'

import Image from 'next/image'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { AdminIcon } from './AdminIcon'
import { AdminLogoutButton } from './AdminLogoutButton'
import { useAdminSession } from './AdminSessionContext'
import { useMediaSlot } from '@/components/site/MediaSlotProvider'
import { useLocalPreference } from '@/lib/admin/use-local-preference'
import { getAdminNavItemsForRole, type AdminNavItem } from '@/data/admin-nav'

/*
 * Kerangka setiap halaman admin: rel navigasi, palet perintah, dan kepala
 * halaman.
 *
 * Bentuk lamanya menaruh judul halaman setinggi 168px di puncak layar, jadi
 * setiap kali pengurus berpindah menu yang pertama terlihat adalah judul —
 * padahal ia sudah tahu menu apa yang baru saja diklik. Yang benar-benar
 * ditanyakan mata saat berpindah adalah "aku sekarang di mana, dan apa yang
 * bisa kukerjakan", jadi puncak layar sekarang berisi remah jejak setinggi
 * satu baris dan pekerjaannya mulai lebih awal.
 *
 * Dua hal disimpan di localStorage, bukan di state saja: lebar rel dan kelompok
 * mana yang terlipat. Keduanya kebiasaan, bukan data — pengurus yang melipat
 * rel sekali berarti ia mau rel terlipat, bukan mau melipatnya lagi di setiap
 * halaman. Lihat useLocalPreference untuk kenapa keduanya tidak dibaca lewat
 * useEffect.
 *
 * Kelompok yang sedang dilipat TETAP boleh dilipat walau memuat halaman
 * sekarang. Memaksanya terbuka akan membuat satu klik pengurus tidak
 * menghasilkan apa-apa, dan tombol yang tidak menuruti klik selalu terbaca
 * rusak. Yang dipakai sebagai gantinya titik emas di judul kelompoknya.
 */

type AdminShellProps = {
  activeHref: string
  children: React.ReactNode
  description?: string
  kicker: string
  title: string
  hidePageHead?: boolean
  visualStyle?: 'default' | 'v7'
}

const navigationGroups = [
  ['workspace', 'Workspace'],
  ['publikasi', 'Publikasi'],
  ['organisasi', 'Organisasi'],
  ['sistem', 'Sistem'],
] as const satisfies ReadonlyArray<readonly [AdminNavItem['group'], string]>

const RAIL_KEY = 'hmte-admin-rail-collapsed'
const GROUP_KEY = 'hmte-admin-nav-closed'

// Tetapan tingkat modul, bukan larik baru tiap render: nilai ini dipakai
// sebagai potret server oleh useLocalPreference, dan potret server harus
// memulangkan rujukan yang sama setiap kali.
const NO_CLOSED_GROUPS: string[] = []

function ChevronIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
      <path d="m9 6 6 6-6 6" />
    </svg>
  )
}

function SearchIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round">
      <circle cx="11" cy="11" r="7" />
      <path d="m20 20-3.6-3.6" />
    </svg>
  )
}

function BellIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M6 10a6 6 0 0 1 12 0c0 4 2 5 2 6H4c0-1 2-2 2-6Z" />
      <path d="M10 20h4" />
    </svg>
  )
}

function PlusIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
      <path d="M12 5v14M5 12h14" />
    </svg>
  )
}

function RailIcon({ collapsed }: { collapsed: boolean }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="4" width="18" height="16" rx="2" />
      <path d="M9 4v16" />
      <path d={collapsed ? 'm13 9 3 3-3 3' : 'm17 9-3 3 3 3'} />
    </svg>
  )
}

export function AdminShell({
  activeHref,
  children,
  description,
  kicker,
  title,
  hidePageHead = false,
  visualStyle = 'default',
}: AdminShellProps) {
  const logo = useMediaSlot('brand.logo.primary')
  const session = useAdminSession()
  const navItems = useMemo(() => getAdminNavItemsForRole(session.role), [session.role])

  const [isNavigationOpen, setIsNavigationOpen] = useState(false)
  const [isPaletteOpen, setIsPaletteOpen] = useState(false)
  const [isRailCollapsed, setIsRailCollapsed] = useLocalPreference(RAIL_KEY, false)
  const [closedGroups, setClosedGroups] = useLocalPreference(GROUP_KEY, NO_CLOSED_GROUPS)

  const activeGroup = navItems.find((item) => item.href === activeHref)?.group
  const groupLabel = navigationGroups.find(([group]) => group === activeGroup)?.[1] ?? kicker

  const toggleRail = useCallback(() => {
    setIsRailCollapsed(!isRailCollapsed)
  }, [isRailCollapsed, setIsRailCollapsed])

  const toggleGroup = useCallback((group: string) => {
    setClosedGroups(
      closedGroups.includes(group) ? closedGroups.filter((entry) => entry !== group) : [...closedGroups, group],
    )
  }, [closedGroups, setClosedGroups])

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault()
        setIsPaletteOpen(true)
      }
      if (event.key === 'Escape') setIsPaletteOpen(false)
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  const initials = (session.displayName || session.email)
    .split(/\s+|@/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('')

  const shellClass = [
    'admin-dashboard',
    visualStyle === 'v7' ? 'admin-shell-v7' : '',
    isNavigationOpen ? 'is-nav-open' : '',
    isRailCollapsed ? 'is-rail-collapsed' : '',
  ].filter(Boolean).join(' ')

  return (
    <main className={shellClass}>
      <aside className="admin-sidebar" aria-label="Navigasi admin" id="admin-navigation">
        <div className="admin-sidebar-main">
          <div className="admin-brand-row">
            <Link className="admin-brand" href="/admin" aria-label="Dashboard admin HMTE">
              <span className="admin-brand-mark">
                <Image src={logo.url} alt={logo.alt} width={112} height={33} priority />
              </span>
              <span className="admin-brand-copy">
                <strong>HMTE</strong>
                <small>Control room</small>
              </span>
            </Link>
            <button
              className="admin-rail-toggle"
              type="button"
              aria-label={isRailCollapsed ? 'Lebarkan navigasi' : 'Ciutkan navigasi'}
              title={isRailCollapsed ? 'Lebarkan navigasi' : 'Ciutkan navigasi'}
              onClick={toggleRail}
            >
              <RailIcon collapsed={isRailCollapsed} />
            </button>
            <button className="admin-nav-close" type="button" aria-label="Tutup navigasi" onClick={() => setIsNavigationOpen(false)}>
              ×
            </button>
          </div>

          <button className="admin-nav-search" type="button" onClick={() => setIsPaletteOpen(true)}>
            <SearchIcon />
            <span>Cari menu</span>
            <kbd>Ctrl K</kbd>
          </button>

          <nav className="admin-nav">
            {navigationGroups.map(([group, label]) => {
              const groupItems = navItems.filter((item) => item.group === group)
              if (groupItems.length === 0) return null

              const isOpen = !closedGroups.includes(group)
              const holdsActive = groupItems.some((item) => item.href === activeHref)

              return (
                <div className="admin-nav-group" key={group} data-open={isOpen} data-active={holdsActive || undefined}>
                  <button
                    className="admin-nav-label"
                    type="button"
                    aria-expanded={isOpen}
                    onClick={() => toggleGroup(group)}
                  >
                    <ChevronIcon />
                    <span>{label}</span>
                    <i>{groupItems.length}</i>
                  </button>

                  <div className="admin-nav-items" hidden={!isOpen}>
                    {groupItems.map((item) => (
                      <Link
                        href={item.href}
                        aria-current={item.href === activeHref ? 'page' : undefined}
                        key={item.href}
                        title={item.label}
                        onClick={() => setIsNavigationOpen(false)}
                      >
                        <AdminIcon name={item.icon} />
                        <span>{item.label}</span>
                      </Link>
                    ))}
                  </div>
                </div>
              )
            })}
          </nav>
        </div>

        <div className="admin-sidebar-footer">
          <div className="admin-user-card">
            <span className="admin-user-avatar">{initials || 'AD'}</span>
            <span>
              <strong>{session.displayName || 'Admin HMTE'}</strong>
              <small>{session.role}</small>
            </span>
          </div>
          <Link className="admin-site-link" href="/" target="_blank" rel="noopener noreferrer" title="Buka website publik">
            <span>Buka website publik</span>
            <i aria-hidden="true">↗</i>
          </Link>
        </div>
      </aside>

      <button className="admin-nav-backdrop" type="button" aria-label="Tutup navigasi" onClick={() => setIsNavigationOpen(false)} />

      <section className="admin-main">
        <header className="admin-topbar">
          <div className="admin-topbar-lead">
            <button
              className="admin-nav-toggle"
              type="button"
              aria-controls="admin-navigation"
              aria-expanded={isNavigationOpen}
              aria-label="Buka navigasi admin"
              onClick={() => setIsNavigationOpen(true)}
            >
              <span />
              <span />
              <span />
            </button>
            <nav className="admin-crumbs" aria-label="Remah jejak">
              <Link href="/admin">Control room</Link>
              <i aria-hidden="true">/</i>
              {visualStyle === 'v7' ? <b>{title}</b> : (
                <>
                  <span>{groupLabel}</span>
                  <i aria-hidden="true">/</i>
                  <b>{title}</b>
                </>
              )}
            </nav>
          </div>
          <div className="admin-topbar-actions">
            {visualStyle === 'v7' ? (
              <>
                <button className="admin-v7-topbar-button" type="button" onClick={() => setIsPaletteOpen(true)} aria-label="Cari menu">
                  <SearchIcon />
                </button>
                <button className="admin-v7-topbar-button" type="button" aria-label="Notifikasi">
                  <BellIcon />
                </button>
                <button className="admin-v7-topbar-button admin-v7-topbar-plus" type="button" onClick={() => setIsPaletteOpen(true)} aria-label="Buat publikasi">
                  <PlusIcon />
                </button>
                <span className="admin-v7-topbar-user">
                  <span className="admin-user-avatar">{initials || 'AD'}</span>
                  <span><strong>{session.displayName || 'Admin HMTE'}</strong><small>HMTE · 2026/2027</small></span>
                </span>
              </>
            ) : (
              <>
                <button className="admin-topbar-search" type="button" onClick={() => setIsPaletteOpen(true)} aria-label="Cari menu">
                  <SearchIcon />
                </button>
                <span className="admin-role-chip">{session.role}</span>
                <AdminLogoutButton />
              </>
            )}
          </div>
        </header>

        <div className="admin-workspace">
          {!hidePageHead ? (
            <div className="admin-page-head">
              <span className="admin-kicker">{kicker}</span>
              <h1>{title}</h1>
              {description ? <p>{description}</p> : null}
            </div>
          ) : null}
          {children}
        </div>
      </section>

      {isPaletteOpen ? (
        <AdminCommandPalette activeHref={activeHref} items={navItems} onClose={() => setIsPaletteOpen(false)} />
      ) : null}
    </main>
  )
}

/**
 * Pencarian menu. Empat belas menu masih muat dilihat sekaligus, tetapi
 * membacanya satu per satu untuk menemukan satu tetap lebih lambat daripada
 * mengetik tiga huruf — dan pengurus yang sudah hafal namanya tidak perlu
 * membaca rel sama sekali.
 */
function AdminCommandPalette({
  activeHref,
  items,
  onClose,
}: {
  activeHref: string
  items: readonly AdminNavItem[]
  onClose: () => void
}) {
  const router = useRouter()
  const inputRef = useRef<HTMLInputElement>(null)
  const [query, setQuery] = useState('')
  const [cursor, setCursor] = useState(0)

  const results = useMemo(() => {
    const needle = query.trim().toLowerCase()
    if (!needle) return items
    return items.filter((item) => item.label.toLowerCase().includes(needle) || item.href.includes(needle))
  }, [items, query])

  useEffect(() => { inputRef.current?.focus() }, [])

  // Penunjuk dikembalikan ke atas di tempat kuerinya berubah, bukan lewat efek
  // yang mengejar perubahan itu setelahnya.
  function onQueryChange(value: string) {
    setQuery(value)
    setCursor(0)
  }

  function go(href: string) {
    onClose()
    router.push(href)
  }

  function onKeyDown(event: React.KeyboardEvent) {
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      setCursor((current) => Math.min(current + 1, results.length - 1))
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      setCursor((current) => Math.max(current - 1, 0))
    }
    if (event.key === 'Enter' && results[cursor]) {
      event.preventDefault()
      go(results[cursor].href)
    }
  }

  return (
    <div className="admin-palette" role="dialog" aria-modal="true" aria-label="Cari menu admin">
      <button className="admin-palette-scrim" type="button" aria-label="Tutup pencarian" onClick={onClose} />
      <div className="admin-palette-box">
        <div className="admin-palette-field">
          <SearchIcon />
          <input
            ref={inputRef}
            value={query}
            placeholder="Ketik nama menu, mis. berkas, berita, aspirasi..."
            onChange={(event) => onQueryChange(event.target.value)}
            onKeyDown={onKeyDown}
          />
          <kbd>Esc</kbd>
        </div>

        {results.length === 0 ? (
          <p className="admin-palette-empty">Tidak ada menu yang cocok dengan “{query}”.</p>
        ) : (
          <ul className="admin-palette-list">
            {results.map((item, index) => (
              <li key={item.href}>
                <button
                  type="button"
                  data-cursor={index === cursor || undefined}
                  data-current={item.href === activeHref || undefined}
                  onMouseEnter={() => setCursor(index)}
                  onClick={() => go(item.href)}
                >
                  <AdminIcon name={item.icon} />
                  <span>{item.label}</span>
                  <small>{item.href}</small>
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}
