'use client'

import { useCallback, useSyncExternalStore } from 'react'

/*
 * Preferensi tampilan yang bertahan antar halaman — lebar rel navigasi,
 * kelompok menu mana yang dilipat.
 *
 * Dibaca lewat useSyncExternalStore, bukan useState + useEffect, dan itu bukan
 * pilihan gaya. localStorage tidak ada di server, jadi render pertama di sana
 * SELALU memakai nilai bawaan; kalau klien membaca localStorage lebih awal,
 * kedua render itu berbeda dan React memprotes ketidakcocokan hidrasi. Hook ini
 * memang dibuat untuk keadaan itu: React memakai potret server selama hidrasi,
 * lalu langsung merender ulang dengan nilai sesungguhnya.
 *
 * Nilainya disimpan di satu penyimpan per kunci di tingkat modul, jadi dua
 * komponen yang membaca kunci sama melihat nilai yang sama dan ikut berubah
 * bersamaan.
 */

type PreferenceStore<Value> = {
  getSnapshot: () => Value
  setValue: (value: Value) => void
  subscribe: (listener: () => void) => () => void
}

const stores = new Map<string, PreferenceStore<unknown>>()

function createStore<Value>(key: string, fallback: Value): PreferenceStore<Value> {
  const listeners = new Set<() => void>()
  let value = fallback
  let isLoaded = false

  return {
    /*
     * Wajib mengembalikan rujukan yang SAMA selama tidak ada perubahan. Kalau
     * ia memulangkan objek baru tiap dipanggil, React menganggap penyimpannya
     * berubah terus dan merender tanpa henti — karena itu hasilnya disinggahkan
     * dan hanya diganti di setValue.
     */
    getSnapshot() {
      if (!isLoaded) {
        isLoaded = true
        try {
          const raw = window.localStorage.getItem(key)
          if (raw !== null) value = JSON.parse(raw) as Value
        } catch {
          // Penyimpanan lokal bisa ditolak (mode privat, kebijakan peramban).
          // Kalau begitu preferensinya cuma tidak bertahan; panel tetap jalan.
        }
      }
      return value
    },

    setValue(next) {
      isLoaded = true
      value = next
      try {
        window.localStorage.setItem(key, JSON.stringify(next))
      } catch {}
      listeners.forEach((listener) => listener())
    },

    subscribe(listener) {
      listeners.add(listener)
      return () => { listeners.delete(listener) }
    },
  }
}

/**
 * `fallback` harus tetapan tingkat modul kalau bentuknya larik atau objek.
 * Nilai inilah yang dipakai sebagai potret server, dan React mensyaratkan
 * potret server memulangkan rujukan yang sama setiap kali.
 */
export function useLocalPreference<Value>(key: string, fallback: Value): [Value, (value: Value) => void] {
  let store = stores.get(key) as PreferenceStore<Value> | undefined

  if (!store) {
    store = createStore(key, fallback)
    stores.set(key, store as PreferenceStore<unknown>)
  }

  const active = store
  const value = useSyncExternalStore(active.subscribe, active.getSnapshot, () => fallback)
  const setValue = useCallback((next: Value) => active.setValue(next), [active])

  return [value, setValue]
}
